insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-so-236","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solution freezes at −0.372 °C. With $K_f = 1.86$ K kg mol⁻¹ the molality of the non-electrolyte is","options":["0.20 m","0.372 m","1.86 m","0.50 m"],"answer_index":0,"explanation":"$m = 0.372 / 1.86 = 0.20$ mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-237","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea versus NaCl, both 0.10 molal in water: the larger freezing-point depression is shown by","options":["NaCl, which supplies more particles","urea","the two matching exactly","neither sample freezing"],"answer_index":0,"explanation":"NaCl gives two ions, so i ≈ 2 and $\\Delta T_f$ is about twice that of urea.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-238","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solute (M = 128 g mol⁻¹), 6.4 g, in 100 g of a solvent ($K_f = 5.0$ K kg mol⁻¹) depresses the freezing point by","options":["2.5 K","5.0 K","0.50 K","1.28 K"],"answer_index":0,"explanation":"n = 0.050 mol in 0.100 kg, so m = 0.50 mol kg⁻¹ and $\\Delta T_f = 5.0 \\times 0.50 = 2.5$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"freezing-depression","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-239","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A 0.050 m AlCl3 solution, taken as fully split (i = 4) in water ($K_f = 1.86$ K kg mol⁻¹), has $\\Delta T_f$ nearest","options":["0.372 K","0.093 K","1.86 K","0.744 K"],"answer_index":0,"explanation":"$\\Delta T_f = 4 \\times 1.86 \\times 0.050 = 0.372$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"freezing-depression","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-240","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Acetic acid in benzene is 60% dimerised. For a 0.20 m solution ($K_f$ of benzene = 5.12 K kg mol⁻¹), $\\Delta T_f$ is nearest","options":["0.72 K","1.02 K","0.20 K","2.56 K"],"answer_index":0,"explanation":"For dimerisation $i = 1 - \\alpha/2 = 0.70$; $\\Delta T_f = 0.70 \\times 5.12 \\times 0.20 \\approx 0.72$ K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"freezing-depression","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-241","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Osmosis is the spontaneous flow of solvent through a semipermeable membrane toward the","options":["more concentrated solution","less concentrated solution","vapour phase","undissolved solid solute"],"answer_index":0,"explanation":"Solvent moves to dilute the side with the higher solute concentration.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-242","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The extra pressure that must be applied on the solution to stop osmosis is called the","options":["osmotic pressure","vapour pressure","Henry pressure","atmospheric pressure only"],"answer_index":0,"explanation":"That balancing pressure is the definition of osmotic pressure $\\pi$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-243","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"van’t Hoff wrote the dilute-solution law in the form","options":["$\\pi = CRT$","$\\pi = K_H x$","$\\pi = K_b m$","$\\pi = p^\\circ x$"],"answer_index":0,"explanation":"C is the molarity, R the gas constant and T the absolute temperature.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-244","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two solutions that have equal osmotic pressure at the same temperature are called","options":["isotonic","hypertonic","hypotonic","azeotropic"],"answer_index":0,"explanation":"Isotonic solutions produce no net solvent flow across a semipermeable membrane.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-245","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A hypotonic solution, relative to a cell, has","options":["lower osmotic pressure","higher osmotic pressure","identical $\\pi$","zero solvent"],"answer_index":0,"explanation":"Water then enters the cell; the external solution is hypotonic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"osmotic-pressure","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
